<div class="d-flex justify-content-between align-items-center mb-3"><h4>گزارش قیمت‌ها</h4><div class="d-flex gap-2"><a class="btn btn-outline-success" href="/pricing/public/reports/export">CSV</a><a class="btn btn-outline-success" href="/pricing/public/exports/prices/excel">Excel</a></div></div><form class="row g-2 mb-3"><div class="col-md-4"><input name="q" value="<?=\App\Core\Security::e($q)?>" class="form-control" placeholder="کد یا نام"></div><div class="col-md-3"><select name="category_id" class="form-select"><option value="0">همه دسته‌ها</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category==$c['id']?'selected':''?>><?=\App\Core\Security::e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select name="importance" class="form-select"><option value="0">همه اهمیت‌ها</option><option value="1" <?=$importance===1?'selected':''?>>عادی</option><option value="2" <?=$importance===2?'selected':''?>>مهم</option><option value="3" <?=$importance===3?'selected':''?>>بحرانی</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">فیلتر</button></div></form><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>کد</th><th>محصول</th><th>دسته</th><th>اهمیت</th><th>واحد</th><th>آخرین تاریخ</th><th>حداقل</th><th>حداکثر</th><th>میانگین</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=\App\Core\Security::e($r['product_code'])?></td><td><?=\App\Core\Security::e($r['product_name'])?></td><td><?=\App\Core\Security::e($r['category_name'])?></td><td><?=$r['importance']?></td><td><?=\App\Core\Security::e($r['unit_name'])?></td><td><?=\App\Core\Security::e($r['latest_date'])?></td><td><?=number_format((float)$r['min_price'],2)?></td><td><?=number_format((float)$r['max_price'],2)?></td><td><?=number_format((float)$r['avg_price'],2)?></td></tr><?php endforeach;?></tbody></table></div>